        const float* xs[3] = { xa, xb, xc };
        float* outs[3] = { outa, outb, outc };
        for (int k = 0; k < 12; k++) {
            _mm256_store_ps(t, *accs[k]);
            float v = t[0] + t[1] + t[2] + t[3] + t[4] + t[5] + t[6] + t[7];
            const size_t row = (size_t)(k & 3);
            const int col = k / 4;
            for (size_t j = i; j < n; j++) v += r[row * stride + j] * xs[col][j];
